def solve():
    for n in range(1, 11):
        best_f = 0
        f_star = (n-1) * (n-2) // 2
        best_f = max(best_f, f_star)
        for a in range(1, n):
            b = n - a
            f_bip = a * (a - 1) // 2 + b * (b - 1) // 2
            best_f = max(best_f, f_bip)
        if n > 3:
            best_f = max(best_f, n)
        print(f"n={n}, best_f={best_f}, f_star={f_star}")

solve()
